/* ---- tiny markdown ---- */
const inl=s=>esc(s).replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/(^|[^*])\*([^*\n]+)\*/g,'$1<em>$2</em>');
function md(text){const blocks=[];text=text.replace(/```\w*\n?([\s\S]*?)```/g,(m,c)=>{blocks.push(c.replace(/\n$/,''));return'\u0000'+(blocks.length-1)+'\u0000'});
let out='',list=null,para=[],tbl=[],m;
const fP=()=>{if(para.length){out+='<p>'+para.map(inl).join('<br>')+'</p>';para=[]}},fL=()=>{if(list){out+='</'+list+'>';list=null}},
fT=()=>{if(!tbl.length)return;const rows=tbl.filter(r=>!(/^[\s|:-]+$/.test(r)&&r.includes('-'))).map(r=>r.trim().replace(/^\||\|$/g,'').split('|').map(c=>c.trim()));out+='<div class="aitw"><table>'+rows.map((r,i)=>'<tr>'+r.map(c=>(i?'<td>':'<th>')+inl(c)+(i?'</td>':'</th>')).join('')+'</tr>').join('')+'</table></div>';tbl=[]};
for(const line of text.split('\n')){
if(/^\s*\|/.test(line)){fP();fL();tbl.push(line);continue}fT();
if((m=line.match(/^\u0000(\d+)\u0000$/))){fP();fL();out+='<pre>'+esc(blocks[m[1]])+'</pre>'}
else if((m=line.match(/^\s*[-*•]\s+(.*)/))){fP();if(list!=='ul'){fL();out+='<ul>';list='ul'}out+='<li>'+inl(m[1])+'</li>'}
else if((m=line.match(/^\s*\d+[.)]\s+(.*)/))){fP();if(list!=='ol'){fL();out+='<ol>';list='ol'}out+='<li>'+inl(m[1])+'</li>'}
else if((m=line.match(/^#{1,4}\s+(.*)/))){fP();fL();out+='<h4>'+inl(m[1])+'</h4>'}
else if(!line.trim()){fP();fL()}
else{fL();para.push(line)}}
fP();fL();fT();return out}

