async function chk(){if(!/^https?:$/.test(location.protocol)||navigator.onLine===false||Date.now()-lastChk<3e5)return;lastChk=Date.now();try{if(sessionStorage.getItem('upd.no')===String(curV()))return}catch(e){}
try{const r=await fetch('index.html',{cache:'no-store'});if(!r.ok)return;const m=/app\.js\?v=(\d+)/.exec(await r.text());if(m&&+m[1]>curV())banner(+m[1])}catch(e){}}
function banner(v){if($('#upd'))return;const e=document.createElement('div');e.id='upd';e.className='upd';e.setAttribute('role','status');
e.innerHTML=`<span>🔄 ${XL('A new version is ready.','নতুন সংস্করণ তৈরি।')}</span><button type="button" data-u="1">${XL('Update','আপডেট')}</button><button type="button" data-u="0" aria-label="${XL('Later','পরে')}">✕</button>`;
e.onclick=async ev=>{const b=ev.target.closest('[data-u]');if(!b)return;if(b.dataset.u==='0'){try{sessionStorage.setItem('upd.no',String(curV()))}catch(x){}e.remove();return}
b.disabled=true;try{const ks=await caches.keys(),k=ks.find(x=>/^budget-v/.test(x));if(k){const c=await caches.open(k),r=await fetch('index.html',{cache:'no-store'});if(r.ok)await c.put('./index.html',r)}}catch(x){}location.reload()};document.body.appendChild(e)}
window.updChk=()=>{lastChk=0;return chk()};
document.addEventListener('visibilitychange',()=>{if(!document.hidden)setTimeout(chk,1500)});setTimeout(chk,4000);
/* ===== 5. backup reminder ===== */
window.fxNots=(n,P,L,d0)=>{if(n.bk===false||U||S.recs.length<10)return;const base=S.lb||S.bs;if(!base)return;const days=Math.floor((Date.now()-base)/864e5);if(days<30)return;
P('bk:'+Math.floor(days/30),'warn','💾',L('You have not backed up your data for '+nn(days)+' days. It is saved only on this phone. Download a backup now, or sign in to keep it in your account.','আপনি '+nn(days)+' দিন ব্যাকআপ নেননি। ডেটা শুধু এই ফোনে আছে। এখনই ব্যাকআপ নামান, অথবা সাইন-ইন করে অ্যাকাউন্টে রাখুন।'),'bk')};
const bsSet=()=>{if(!S.bs&&S.recs.length>=10&&!U){S.bs=Date.now();sv()}};
/* ===== settings block ===== */
window.fxSet=L=>`<span class="sl">🎯 ${L('Daily spending guide','দৈনিক খরচের গাইড')}</span>${tabs('sgt',S.sg===true?'on':'off',[['off',L('Off','বন্ধ')],['on',L('On','চালু')]])}<small style="color:var(--mut)">${L('Off by default. When On, shows how much you can spend today to stay within your monthly budgets (needs budgets to be set) on the Entries and Budgets tabs.','আগে থেকে বন্ধ থাকে। চালু করলে মাসের বাজেটের মধ্যে থাকতে আজ কত খরচ করতে পারবেন তা লেনদেন ও বাজেট ট্যাবে দেখায় (বাজেট ঠিক করা থাকতে হবে)।')}</small>
<span class="sl">⚡ ${L('Quick entries','দ্রুত এন্ট্রি')}</span>${tabs('qkt',S.qkOn===true?'on':'off',[['off',L('Off','বন্ধ')],['on',L('On','চালু')]])}<div class="row"><button class="g" data-a="qko">⚡ ${L('Manage quick entries','দ্রুত এন্ট্রি ম্যানেজ করুন')}</button></div><small style="color:var(--mut)">${L('Off by default. When On, one-tap buttons appear on the Entries tab for things you add again and again.','আগে থেকে বন্ধ থাকে। চালু করলে বারবার করা এন্ট্রির জন্য লেনদেন ট্যাবে এক চাপের বাটন আসে।')}</small>`;
/* ===== hooks into the views ===== */
const bud0=V.bud,rec0=V.rec;
V.bud=function(){const h=hist();return guideHtml()+(h?`<div class="row"><button class="g" data-a="sgs">💡 ${XL('Suggest budgets from my spending','আমার খরচ দেখে বাজেট সাজেস্ট')}</button></div>`:'')+bud0.apply(this,arguments)};
V.rec=function(){return (q?'':guideHtml()+qkHtml())+rec0.apply(this,arguments)};
const find=id=>QK().find(x=>x.id===id);
Object.assign(A,{
sgt:x=>{S.sg=x==='on';sv();R();openSet()},qkt:x=>{S.qkOn=x==='on';sv();R();cs===qkSheet?qkSheet():openSet()},
sgs:()=>{SG=null;sgSheet()},sgk:id=>{if(!SG)return;SG.sel.has(id)?SG.sel.delete(id):SG.sel.add(id);sgSheet()},sgx:()=>{SG=null;A.cl()},
sga:()=>{const h=hist();if(!h||!SG)return;let n=0;h.rows.forEach(r=>{if(SG.sel.has(r.id)){S.b[r.id]=r.sug;n++}});SG=null;if(!n){A.cl();return toast(XL('Nothing selected','কিছু বাছা হয়নি'))}sv();R();A.cl();toast('✓ '+XL(nn(n)+' budget'+(n>1?'s':'')+' set',nn(n)+'টি বাজেট ঠিক হয়েছে'))},
qka:qkAdd,qko:qkSheet,qkn:()=>{Q=qnew();qform()},qke:id=>{const q=find(id);if(!q)return;Q={id:q.id,t:q.t,amt:String(q.amt),acc:q.acc,to:q.to||'',cat:q.cat||'',note:q.note||''};qform()},
qkt2:k=>{qgrab();if(Q.t!==k){Q.t=k;Q.cat='';if(k!=='t')Q.to=''}qform()},qkw:id=>{qgrab();Q.acc=id;qform()},qkw2:id=>{qgrab();Q.to=id;qform()},qks:qsave,
qkx:id=>{if(!confirm(XL('Delete this quick entry?','এই দ্রুত এন্ট্রি মুছবেন?')))return;S.qk=QK().filter(x=>x.id!==id);Q=null;sv();R();qkSheet()},
qkf:i=>{const q=freq().filter(okq)[+i];if(!q)return;const c={id:'q'+Date.now().toString(36),t:q.t,acc:q.acc,amt:q.amt,note:q.note};if(q.t==='t')c.to=q.to;else c.cat=q.cat;QK().push(c);sv();R();qkSheet()},
qkp:id=>{const r=S.recs.find(x=>x.id===id);if(!r||r.lk||r.sv)return;const c={id:'q'+Date.now().toString(36),t:r.t,acc:r.acc,amt:r.amt,note:(r.note||'').trim().slice(0,40)};if(r.t==='t')c.to=r.to;else c.cat=r.cat;
if(QK().some(x=>kOf(x)===kOf(c)))return toast(XL('Already a quick entry','এটি আগেই দ্রুত এন্ট্রিতে আছে'));QK().push(c);sv();R();toast('⚡ '+XL('Saved as a quick entry','দ্রুত এন্ট্রি হিসেবে সেভ হয়েছে')+(S.qkOn===true?'':XL('. Turn Quick entries On in Settings to see the buttons.','। বাটন দেখতে সেটিংসে দ্রুত এন্ট্রি চালু করুন।')))}});
