setTimeout(()=>{try{const u=new URLSearchParams(location.search),k=u.get('add');if(k!=='e'&&k!=='i')return;history.replaceState(null,'',location.pathname);A.tab&&A.tab('rec');recForm({dup:1,t:k,acc:'',cat:'',to:'',note:'',amt:'',ts:Date.now()})}catch(e){}},350);
